'use strict';
/**
 * PF102B — ORIGINAL EveJS WORK source-only composition.
 *
 * No user-facing command, JSON/env override, dummy NPC identity, salary
 * default, alternate wallet, original ItemStore writer or private arbiter.
 * Two separately source-owned artifacts are mandatory:
 *
 *   ./coopPersonalFleetOriginalAuthoredPolicy
 *   ./coopPersonalFleetOriginalNativeWriterBoundary
 *
 * Those are NOT generated by this module: the original WORK engine owner
 * must author the policy from verified SDE and supply independently
 * fenced writer-owner hooks from the real engine. An absent source aborts
 * the feature before TCP listens. Never install this into PLAY by default.
 */
const bootstrap=require('./coopPersonalFleetOriginalWorkBootstrap');
const SOURCE='ORIGINAL_EVEJS_PERSONAL_FLEET_WORK_CONFIGURATION_V1';
const POLICY_SOURCE='ORIGINAL_EVEJS_PERSONAL_FLEET_AUTHORED_POLICY_V1';
const WRITER_SOURCE='ORIGINAL_EVEJS_PERSONAL_FLEET_NATIVE_WRITERS_V1';
const TOKEN=/^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$/;
const positive=x=>Number.isSafeInteger(x)&&x>0;
const obj=x=>x!==null&&typeof x==='object'&&!Array.isArray(x);
const fields={
 catalog:['npcCharacterID','employerCorpID','profileID','shipTypeID','amountCents'],
 salary:['npcCharacterID','employerCorpID','profileID','shipTypeID','salaryCents','periodMs']
};
const exactly=(x,keys)=>obj(x)&&Object.keys(x).length===keys.length&&
 keys.every(k=>Object.prototype.hasOwnProperty.call(x,k));
const validID=x=>typeof x==='string'&&TOKEN.test(x);
const shared=c=>[c.npcCharacterID,c.employerCorpID,c.profileID,c.shipTypeID].join(':');
const safeLoad=(sourceName,errorCode)=>{
 try{return require(sourceName);}
 catch(e){throw Error(errorCode+':'+String(e?.code||'SOURCE_LOAD_FAILED'));}
};
let snapshot=null;
function load(){
 if(snapshot)return snapshot;
 const authored=safeLoad('./coopPersonalFleetOriginalAuthoredPolicy',
  'PF102B_SOURCE_AUTHORED_NPC_POLICY_NOT_INSTALLED');
 if(!obj(authored)||authored.source!==POLICY_SOURCE||
    !exactly(authored,['source','catalog','salaryPolicies'])||
    !Array.isArray(authored.catalog)||!Array.isArray(authored.salaryPolicies)||
    authored.catalog.length<1||authored.catalog.length>12||
    authored.catalog.length!==authored.salaryPolicies.length)
  throw Error('PF102B_ORIGINAL_NATIVE_POLICY_INCOMPLETE');
 const ids=new Set(),catalog=[];
 for(const v of authored.catalog){
  if(!exactly(v,fields.catalog)||
     ![v.npcCharacterID,v.employerCorpID,v.shipTypeID,v.amountCents].every(positive)||
     v.amountCents>1000000000000||!validID(v.profileID)||
     ids.has(v.npcCharacterID))
   throw Error('PF102B_ORIGINAL_NPC_CATALOG_INVALID_OR_DUPLICATE');
  ids.add(v.npcCharacterID);
  catalog.push(Object.freeze({...v}));
 }
 const payIds=new Set(),policies=[];
 for(const v of authored.salaryPolicies){
  if(!exactly(v,fields.salary)||
     ![v.npcCharacterID,v.employerCorpID,v.shipTypeID,v.salaryCents].every(positive)||
     v.salaryCents>1000000000000||!validID(v.profileID)||
     !Number.isSafeInteger(v.periodMs)||
     v.periodMs<3600000||v.periodMs>604800000||
     payIds.has(v.npcCharacterID))
   throw Error('PF102B_ORIGINAL_NPC_SALARY_POLICY_INVALID');
  payIds.add(v.npcCharacterID);
  policies.push(Object.freeze({...v}));
 }
 if(ids.size!==payIds.size||catalog.some(c=>
   policies.filter(p=>shared(c)===shared(p)).length!==1))
  throw Error('PF102B_ORIGINAL_NPC_WAGES_NOT_ONE_TO_ONE');
 // Only these explicitly authored primitives are kept; no mutable external
 // policy references are exposed or read again after first valid load.
 snapshot=Object.freeze({
  catalog:Object.freeze(catalog),salaryPolicies:Object.freeze(policies)
 });
 return snapshot;
}
function loadNativeAuthoredCatalog(){
 return load().catalog.map(x=>({...x}));
}
function loadNativeSalaryPolicies(){
 return load().salaryPolicies.map(x=>({...x}));
}
function createNativeWriterHooks(){
 // Strict source import, never imported from a path/env/client/HTTP option.
 const writers=safeLoad('./coopPersonalFleetOriginalNativeWriterBoundary',
  'PF102B_ORIGINAL_NATIVE_WRITER_BOUNDARY_NOT_INSTALLED');
 if(!obj(writers)||writers.source!==WRITER_SOURCE||
    typeof writers.createNativeWriterHooks!=='function')
  throw Error('PF102B_ORIGINAL_NATIVE_WRITER_BOUNDARY_INVALID');
 const hooks=writers.createNativeWriterHooks();
 if(!obj(hooks)||hooks.source!=='ORIGINAL_EVEJS_PERSONAL_FLEET_BOOT_OWNER_V1'||
    !Array.isArray(bootstrap.HOOKS)||
    !bootstrap.HOOKS.every(name=>typeof hooks[name]==='function')||
    !obj(hooks.claimsPolicy)||
    hooks.claimsPolicy.KEY!=='coop-personal-fleet\u001factor-claims-v1'||
    typeof hooks.claimsPolicy.validate!=='function'||
    typeof hooks.claimsPolicy.empty!=='function'||
    !obj(hooks.sharedOriginalNpcOrderArbiter)||
    !['issue','blocked','snapshot','retainWithNativeProof','blocksForSystem'].every(
      name=>typeof hooks.sharedOriginalNpcOrderArbiter[name]==='function')||
    ['gameStore','stockItemStore','originalRuntime','sessionRegistry',
      'nativeNpcStore','nativeNpcService','nativeNpcRegistry','access'].some(
      name=>Object.prototype.hasOwnProperty.call(hooks,name)))
  throw Error('PF102B_ORIGINAL_NATIVE_WRITER_HOOK_CONTRACT_INVALID');
 // OriginalWorkStarter independently requires three real reciprocal writer
 // attestations == true BEFORE the first business owner is installed.
 return hooks;
}
module.exports=Object.freeze({source:SOURCE,loadNativeAuthoredCatalog,
 loadNativeSalaryPolicies,createNativeWriterHooks});
